@startuml

class Employee {
  + Name : string
  + Ssn : int
}

class Driver extends Employee {}

class Planner extends Employee {
  + Username : string
  + Password : string
}

class AdministrativeStaff extends Employee {
  + Username : string
  + Password : string
  + FieldOfActivity : string
}

class Customer {
  + Name : string
  + BillingAddress : string
}

class PartnerCompany {
  + Name : string
  + Address : string
}

class Vehicle {
  + LicensePlateNumber : string
  + Mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + Name : string
  + Address : string
}

class Repair {
  + Duration : string
  + Cost : float
}

class Order {
  + PackageSize : string
  + Comment : string
  + StartTime : datetime
  + FinishTime : datetime
  + PickUpAddress : string
  + DeliveryAddress : string
}

Employee "1" -- "*" Repair : takes vehicle to
Vehicle "1" -- "*" Repair : undergoes
RepairShop "1" -- "*" Repair : hosts

Driver "1" -- "*" Order : assigned to
Driver "1" -- "*" Order : completes
Vehicle "1" -- "*" Order : used in
Planner "1" -- "*" Order : assigns
Customer "1" -- "*" Order : client
AdministrativeStaff "0..1" -- "*" Order : places
PartnerCompany "0..1" -- "*" Order : places

@enduml

